  "game.items.artefact_doom_1_description": "Mảnh đá đen khiến người ta bất an. Có thứ gì đó được khắc trên đá bằng một ngôn ngữ xa lạ.",
  "game.items.artefact_doom_1_name": "Đá núi lửa",
  "game.items.artefact_doom_2_description": "Chiếc chìa khóa nặng, trang trí hình con lươn quỷ được chạm khắc tinh vi đến mức gần như còn sống. Sờ vào thấy lạnh một cách kỳ lạ.",
  "game.items.artefact_doom_2_name": "Chìa khóa đền",
  "game.items.artefact_doom_3_description": "Vỏ sò mỏng manh màu vàng và hồng nhạt, hẳn đã được lấy từ một viện bảo tàng.",
  "game.items.artefact_doom_3_name": "Vỏ sò",
  "game.items.artefact_doom_4_description": "Tờ truyền đơn chính trị in trên giấy dày, kêu gọi cư dân các 'cống ngầm' nổi dậy chống lại sự phân biệt đối xử.",
  "game.items.artefact_doom_4_name": "Truyền đơn phản loạn",
  "game.items.artefact_doom_5_description": "Bản đồ chiêm tinh phức tạp, kèm những phép tính cho thấy một sự kiện sẽ xảy ra vào năm 783.",
  "game.items.artefact_doom_5_name": "Bản đồ sao",
  "game.items.artefact_doom_6_description": "Bức tượng nhỏ làm từ dây kim loại, nhưng mỗi người nhìn vào lại thấy một hình dạng khác nhau",
  "game.items.artefact_doom_6_name": "Vật trang trí bất an",
  "game.items.artefact_doom_7_description": "Con châu chấu kim loại nhỏ nhưng tinh xảo; từng có cả đàn châu chấu như vậy tấn công các khu định cư và nuốt chửng tài nguyên của họ",
  "game.items.artefact_doom_7_name": "Châu chấu cơ khí bất động",
  "game.items.artefact_fall_1_description": "Tấm áp phích chép tay mô tả một người thân mất tích từ sau Đại Sụp Đổ.",
  "game.items.artefact_fall_1_name": "Áp phích người mất tích",
  "game.items.artefact_fall_2_description": "Hàng hàng dòng nhật ký lỗi được một hệ thống máy tính in ra giấy vào thời điểm Đại Sụp Đổ.",
  "game.items.artefact_fall_2_name": "Nhật ký lỗi",
  "game.items.artefact_ground_1_description": "Mảnh đá khó hiểu có khắc một chữ rune cổ.",
  "game.items.artefact_ground_1_name": "Đá rune",
  "game.items.artefact_ground_2_description": "Người ta nói hạt giống chứa đựng chính sự sống. Hạt này không thể nảy mầm trong Thành phố bóng tối.",
  "game.items.artefact_ground_2_name": "Hạt giống cháy sém",
  "game.items.artefact_ground_3_description": "Viên đá nhẵn vừa lòng bàn tay. Nó đem lại cảm giác bình tâm kỳ lạ.",
  "game.items.artefact_ground_3_name": "Đá tròn",
  "game.items.artefact_ground_4_description": "Chiếc túi da nhỏ có dây đeo quanh cổ. Bên trong chỉ có một loại bột nào đó.",
  "game.items.artefact_ground_4_name": "Túi da",
  "game.items.artefact_history_1_description": "Đã khô từ lâu và không còn dùng để viết được, nhưng vẫn được các hiền giả ưa chuộng như biểu tượng của tri thức.",
  "game.items.artefact_history_1_name": "Bút máy",
  "game.items.artefact_history_2_description": "Vật trang trí bằng kim loại hình núi lửa, ngọn núi phun lửa từ trái tim luôn chuyển động của hành tinh.",
  "game.items.artefact_history_2_name": "Mặt dây chuyền",
  "game.items.artefact_history_3_description": "Thiết bị lưu trữ dữ liệu dạng đĩa tròn cũ, trên đó có chữ 'sao lưu'. Không có máy tính hoạt động thì không thể biết nó còn đọc được hay không.",
  "game.items.artefact_history_3_name": "Đĩa CD",
  "game.items.artefact_history_4_description": "Con ngựa đồ chơi cũ sờn, nhẹ bất ngờ, có chất liệu ấm kỳ lạ; từ thời gỗ còn chưa phải thứ xa xỉ.",
  "game.items.artefact_history_4_name": "Ngựa đồ chơi bằng gỗ",
  "game.items.artefact_history_5_description": "Tờ rơi tuyên truyền của chính phủ bị rách, quảng bá lợi ích của việc lập gia đình, đặc biệt nhắm đến phụ nữ.",
  "game.items.artefact_history_5_name": "Tờ rơi về sinh nở",
  "game.items.artefact_rescue_1_description": "Chắc chắn đây là đồ của Sunita. Nó có logo GIGA nhưng đã được chỉnh sửa để vừa hơn với bình nước của cô ấy.",
  "game.items.artefact_rescue_1_name": "Ba lô của Sunita",
  "game.items.artefact_surface_1_description": "Đồ ăn thừa từ một thời đã qua. Người ta nói từng có những bể cá ở đâu đó gần mặt đất.",
  "game.items.artefact_surface_1_name": "Cá ngừ đóng hộp",
  "game.items.artefact_surface_2_description": "Những con chip như thế này từng được cấy dưới da người, đem lại cho họ một số năng lực. Có lẽ giờ chúng không còn hoạt động.",
  "game.items.artefact_surface_2_name": "Chip ID",
  "game.items.artefact_surface_3_description": "Cuốn sổ đã sờn nhưng phần lớn vẫn đọc được, dường như chứa các phép tính về mức tiêu thụ nhiên liệu của một loại phương tiện lớn và phức tạp khi di chuyển quãng đường rất dài.",
  "game.items.artefact_surface_3_name": "Sổ tay của nhà khoa học",
  "game.items.artefact_surface_4_description": "Mảnh nhựa trắng hình chữ nhật mỏng từng dùng để mở cửa. Một số người tin nó vẫn còn quyền năng lớn.",
  "game.items.artefact_surface_4_name": "Thẻ khóa nhựa",
  "game.items.artefact_surface_5_description": "Tạp chí sờn rách nhưng vẫn nhiều màu sắc, đầy những câu chuyện kỳ ảo.",
  "game.items.artefact_surface_5_name": "Truyện tranh rách",
  "game.items.artefact_surface_6_description": "Từng là biểu tượng của cuộc sống trên mặt đất, giờ chỉ còn là chiếc mũ trùm vô hồn kỳ lạ.",
  "game.items.artefact_surface_6_name": "Tai nghe",
  "game.items.artefact_surface_7_description": "Nhân vật nhiều màu sắc và đầy hoài niệm trong một trò chơi điện tử",
  "game.items.artefact_surface_7_name": "Tượng nhựa",
