  "story.messages.passage_found_hole_built_message": "Có một thang máy ở đây.",
  "story.messages.passage_found_hole_down_dark_message": "Có một hố sụt khổng lồ ở đây. Bên dưới chỉ nhìn thấy khoảng không vô tận.",
  "story.messages.passage_found_hole_down_sunlit_message": "Có một hố sụt khổng lồ ở đây. Xa tít bên dưới có thể thấy một con phố.",
  "story.messages.passage_found_hole_up_dark_message": "Tít cao trên trần có một cái lỗ, một cái miệng dẫn vào bóng đen.",
  "story.messages.passage_found_hole_up_sunlit_message": "Tít cao trên trần có một cái lỗ dẫn lên tầng trên.",
  "story.messages.passage_found_prebuilt_message": "Có một cầu thang bảo trì ở đây, vẫn còn tốt.",
  "story.messages.passage_found_stairwell_built_message": "Có một cầu thang ở đây.",
  "story.messages.passage_found_stairwell_message": "Từng có một cầu thang ở đây.",
