function flatten(value, path, result) {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    for (const [key, child] of Object.entries(value)) flatten(child, path ? path + "." + key : key, result);
  } else {
    result[path] = value;
  }
  return result;
}

function setPath(object, path, value) {
  const keys = path.split(".");
  let target = object;
  for (let i = 0; i < keys.length - 1; i++) target = target[keys[i]];
  target[keys[keys.length - 1]] = value;
}

const flat = flatten(source, "", {});
const missing = Object.keys(flat).filter((key) => !(key in translations));
if (missing.length) {
  console.error(`Missing Vietnamese translations: ${missing.length}`);
  console.error(missing.slice(0, 20).join("\n"));
  process.exit(1);
}

const output = JSON.parse(JSON.stringify(source));
for (const [key, value] of Object.entries(translations)) setPath(output, key, value);
fs.writeFileSync(outputPath, JSON.stringify(output, null, "\t") + "\n");
console.log(`Wrote ${outputPath} with ${Object.keys(translations).length} translations.`);
